// NULL-tolerant scan buffer for sourceDocumentScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type sourceDocumentPreloadBuf struct {
	ID                sql.Null[uuid.UUID]
	HouseholdID       sql.Null[uuid.UUID]
	Sha256            sql.Null[string]
	ObjectKey         sql.Null[string]
	MimeType          sql.Null[string]
	SourceKind        sql.Null[string]
	Metadata          sql.Null[types.JSON[json.RawMessage]]
	CreatedBy         sql.Null[uuid.UUID]
	CreatedAt         sql.Null[time.Time]
	SourceFilename    sql.Null[string]
	AnalysisObjectKey sql.Null[string]
	AnalysisMimeType  sql.Null[string]
	AnalysisTransform sql.Null[types.JSON[json.RawMessage]]
}

// sourceDocumentScanMapperNullable maps the preloaded sourceDocument
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func sourceDocumentScanMapperNullable(prefix string) scan.Mapper[*SourceDocument] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*SourceDocument, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *sourceDocumentPreloadBuf) any
		}
		targets := make([]target, 0, 13)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *sourceDocumentPreloadBuf) any { return &b.ID }})
			case "household_id":
				targets = append(targets, target{i, func(b *sourceDocumentPreloadBuf) any { return &b.HouseholdID }})
			case "sha256":
				targets = append(targets, target{i, func(b *sourceDocumentPreloadBuf) any { return &b.Sha256 }})
			case "object_key":
				targets = append(targets, target{i, func(b *sourceDocumentPreloadBuf) any { return &b.ObjectKey }})
			case "mime_type":
				targets = append(targets, target{i, func(b *sourceDocumentPreloadBuf) any { return &b.MimeType }})
			case "source_kind":
				targets = append(targets, target{i, func(b *sourceDocumentPreloadBuf) any { return &b.SourceKind }})
			case "metadata":
				targets = append(targets, target{i, func(b *sourceDocumentPreloadBuf) any { return &b.Metadata }})
			case "created_by":
				targets = append(targets, target{i, func(b *sourceDocumentPreloadBuf) any { return &b.CreatedBy }})
			case "created_at":
				targets = append(targets, target{i, func(b *sourceDocumentPreloadBuf) any { return &b.CreatedAt }})
			case "source_filename":
				targets = append(targets, target{i, func(b *sourceDocumentPreloadBuf) any { return &b.SourceFilename }})
			case "analysis_object_key":
				targets = append(targets, target{i, func(b *sourceDocumentPreloadBuf) any { return &b.AnalysisObjectKey }})
			case "analysis_mime_type":
				targets = append(targets, target{i, func(b *sourceDocumentPreloadBuf) any { return &b.AnalysisMimeType }})
			case "analysis_transform":
				targets = append(targets, target{i, func(b *sourceDocumentPreloadBuf) any { return &b.AnalysisTransform }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(sourceDocumentPreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*SourceDocument, error) {
				buf := link.(*sourceDocumentPreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.Valid) &&
					!(buf.HouseholdID.Valid) &&
					!(buf.Sha256.Valid) &&
					!(buf.ObjectKey.Valid) &&
					!(buf.MimeType.Valid) &&
					!(buf.SourceKind.Valid) &&
					!(buf.Metadata.Valid) &&
					!(buf.CreatedBy.Valid) &&
					!(buf.CreatedAt.Valid) &&
					!(buf.SourceFilename.Valid) &&
					!(buf.AnalysisObjectKey.Valid) &&
					!(buf.AnalysisMimeType.Valid) &&
					!(buf.AnalysisTransform.Valid) {
					return nil, nil
				}

				o := new(SourceDocument)
				if buf.ID.Valid {
					o.ID = buf.ID.V
				}
				if buf.HouseholdID.Valid {
					o.HouseholdID = buf.HouseholdID.V
				}
				if buf.Sha256.Valid {
					o.Sha256 = buf.Sha256.V
				}
				if buf.ObjectKey.Valid {
					o.ObjectKey = buf.ObjectKey.V
				}
				if buf.MimeType.Valid {
					o.MimeType = buf.MimeType.V
				}
				if buf.SourceKind.Valid {
					o.SourceKind = buf.SourceKind.V
				}
				if buf.Metadata.Valid {
					o.Metadata = buf.Metadata.V
				}
				if buf.CreatedBy.Valid {
					o.CreatedBy = buf.CreatedBy.V
				}
				if buf.CreatedAt.Valid {
					o.CreatedAt = buf.CreatedAt.V
				}
				o.SourceFilename = buf.SourceFilename
				o.AnalysisObjectKey = buf.AnalysisObjectKey
				o.AnalysisMimeType = buf.AnalysisMimeType
				o.AnalysisTransform = buf.AnalysisTransform
				return o, nil
			}
	}
}

func (o *SourceDocument) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "CorrectionEvidenceLinks":
		rels, ok := retrieved.(CorrectionEvidenceLinkSlice)
		if !ok {
			return fmt.Errorf("sourceDocument cannot load %T as %q", retrieved, name)
		}

		o.R.CorrectionEvidenceLinks = rels
		o.R.Loaded.CorrectionEvidenceLinks = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.SourceDocument = o
				rel.R.Loaded.SourceDocument = true
			}
		}
		return nil
	case "DocumentConfirmations":
		rels, ok := retrieved.(DocumentConfirmationSlice)
		if !ok {
			return fmt.Errorf("sourceDocument cannot load %T as %q", retrieved, name)
		}

		o.R.DocumentConfirmations = rels
		o.R.Loaded.DocumentConfirmations = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.SourceDocument = o
				rel.R.Loaded.SourceDocument = true
			}
		}
		return nil
	case "EvidenceLinks":
		rels, ok := retrieved.(EvidenceLinkSlice)
		if !ok {
			return fmt.Errorf("sourceDocument cannot load %T as %q", retrieved, name)
		}

		o.R.EvidenceLinks = rels
		o.R.Loaded.EvidenceLinks = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.SourceDocument = o
				rel.R.Loaded.SourceDocument = true
			}
		}
		return nil
	case "ExtractionJobs":
		rels, ok := retrieved.(ExtractionJobSlice)
		if !ok {
			return fmt.Errorf("sourceDocument cannot load %T as %q", retrieved, name)
		}

		o.R.ExtractionJobs = rels
		o.R.Loaded.ExtractionJobs = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.SourceDocument = o
				rel.R.Loaded.SourceDocument = true
			}
		}
		return nil
	case "AttachmentsAsChild":
		rels, ok := retrieved.(SourceDocumentAttachmentSlice)
		if !ok {
			return fmt.Errorf("sourceDocument cannot load %T as %q", retrieved, name)
		}

		o.R.AttachmentsAsChild = rels
		o.R.Loaded.AttachmentsAsChild = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.ChildAttachments = o
				rel.R.Loaded.ChildAttachments = true
			}
		}
		return nil
	case "AttachmentsAsParent":
		rels, ok := retrieved.(SourceDocumentAttachmentSlice)
		if !ok {
			return fmt.Errorf("sourceDocument cannot load %T as %q", retrieved, name)
		}

		o.R.AttachmentsAsParent = rels
		o.R.Loaded.AttachmentsAsParent = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.ParentAttachments = o
				rel.R.Loaded.ParentAttachments = true
			}
		}
		return nil
	case "CreatedByMember":
		rel, ok := retrieved.(*Member)
		if !ok {
			return fmt.Errorf("sourceDocument cannot load %T as %q", retrieved, name)
		}

		o.R.CreatedByMember = rel
		o.R.Loaded.CreatedByMember = true

		if rel != nil {
			rel.R.CreatedBySourceDocuments = SourceDocumentSlice{o}
		}
		return nil
	case "Household":
		rel, ok := retrieved.(*Household)
		if !ok {
			return fmt.Errorf("sourceDocument cannot load %T as %q", retrieved, name)
		}

		o.R.Household = rel
		o.R.Loaded.Household = true

		if rel != nil {
			rel.R.SourceDocuments = SourceDocumentSlice{o}
		}
		return nil
	case "SourceObservations":
		rels, ok := retrieved.(SourceObservationSlice)
		if !ok {
			return fmt.Errorf("sourceDocument cannot load %T as %q", retrieved, name)
		}

		o.R.SourceObservations = rels
		o.R.Loaded.SourceObservations = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.SourceDocument = o
				rel.R.Loaded.SourceDocument = true
			}
		}
		return nil
	default:
		return fmt.Errorf("sourceDocument has no relationship %q", name)
	}
}

type sourceDocumentPreloader struct {
	CreatedByMember func(...psql.PreloadOption) psql.Preloader
	Household       func(...psql.PreloadOption) psql.Preloader
}

func buildSourceDocumentPreloader() sourceDocumentPreloader {
	return sourceDocumentPreloader{
		CreatedByMember: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Member, MemberSlice](psql.PreloadRel{
				Name: "CreatedByMember",
				Sides: []psql.PreloadSide{
					{
						From:        SourceDocuments,
						To:          Members,
						FromColumns: []string{"created_by"},
						ToColumns:   []string{"id"},
					},
				},
			}, Members.Columns.Names(), memberScanMapperNullable, opts...)
		},
		Household: func(opts ...psql.PreloadOption) psql.Preloader {
			return psql.Preload[*Household, HouseholdSlice](psql.PreloadRel{
				Name: "Household",
				Sides: []psql.PreloadSide{
					{
						From:        SourceDocuments,
						To:          Households,
						FromColumns: []string{"household_id"},
						ToColumns:   []string{"id"},
					},
				},
			}, Households.Columns.Names(), householdScanMapperNullable, opts...)
		},
	}
}

type sourceDocumentThenLoader[Q orm.Loadable] struct {
	CorrectionEvidenceLinks func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	DocumentConfirmations   func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	EvidenceLinks           func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	ExtractionJobs          func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	AttachmentsAsChild      func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	AttachmentsAsParent     func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	CreatedByMember         func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Household               func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	SourceObservations      func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildSourceDocumentThenLoader[Q orm.Loadable]() sourceDocumentThenLoader[Q] {
	type CorrectionEvidenceLinksLoadInterface interface {
		LoadCorrectionEvidenceLinks(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type DocumentConfirmationsLoadInterface interface {
		LoadDocumentConfirmations(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type EvidenceLinksLoadInterface interface {
		LoadEvidenceLinks(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type ExtractionJobsLoadInterface interface {
		LoadExtractionJobs(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type AttachmentsAsChildLoadInterface interface {
		LoadAttachmentsAsChild(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type AttachmentsAsParentLoadInterface interface {
		LoadAttachmentsAsParent(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type CreatedByMemberLoadInterface interface {
		LoadCreatedByMember(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type HouseholdLoadInterface interface {
		LoadHousehold(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type SourceObservationsLoadInterface interface {
		LoadSourceObservations(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return sourceDocumentThenLoader[Q]{
		CorrectionEvidenceLinks: thenLoadBuilder[Q](
			"CorrectionEvidenceLinks",
			func(ctx context.Context, exec bob.Executor, retrieved CorrectionEvidenceLinksLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCorrectionEvidenceLinks(ctx, exec, mods...)
			},
		),
		DocumentConfirmations: thenLoadBuilder[Q](
			"DocumentConfirmations",
			func(ctx context.Context, exec bob.Executor, retrieved DocumentConfirmationsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadDocumentConfirmations(ctx, exec, mods...)
			},
		),
		EvidenceLinks: thenLoadBuilder[Q](
			"EvidenceLinks",
			func(ctx context.Context, exec bob.Executor, retrieved EvidenceLinksLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadEvidenceLinks(ctx, exec, mods...)
			},
		),
		ExtractionJobs: thenLoadBuilder[Q](
			"ExtractionJobs",
			func(ctx context.Context, exec bob.Executor, retrieved ExtractionJobsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadExtractionJobs(ctx, exec, mods...)
			},
		),
		AttachmentsAsChild: thenLoadBuilder[Q](
			"AttachmentsAsChild",
			func(ctx context.Context, exec bob.Executor, retrieved AttachmentsAsChildLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadAttachmentsAsChild(ctx, exec, mods...)
			},
		),
		AttachmentsAsParent: thenLoadBuilder[Q](
			"AttachmentsAsParent",
			func(ctx context.Context, exec bob.Executor, retrieved AttachmentsAsParentLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadAttachmentsAsParent(ctx, exec, mods...)
			},
		),
		CreatedByMember: thenLoadBuilder[Q](
			"CreatedByMember",
			func(ctx context.Context, exec bob.Executor, retrieved CreatedByMemberLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCreatedByMember(ctx, exec, mods...)
			},
		),
		Household: thenLoadBuilder[Q](
			"Household",
			func(ctx context.Context, exec bob.Executor, retrieved HouseholdLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadHousehold(ctx, exec, mods...)
			},
		),
		SourceObservations: thenLoadBuilder[Q](
			"SourceObservations",
			func(ctx context.Context, exec bob.Executor, retrieved SourceObservationsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadSourceObservations(ctx, exec, mods...)
			},
		),
	}
}

// LoadCorrectionEvidenceLinks loads the sourceDocument's CorrectionEvidenceLinks into the .R struct
func (o *SourceDocument) LoadCorrectionEvidenceLinks(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.CorrectionEvidenceLinks = nil
	o.R.Loaded.CorrectionEvidenceLinks = false

	related, err := o.CorrectionEvidenceLinks(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.SourceDocument = o
		rel.R.Loaded.SourceDocument = true
	}

	o.R.CorrectionEvidenceLinks = related
	o.R.Loaded.CorrectionEvidenceLinks = true
	return nil
}

// LoadCorrectionEvidenceLinks loads the sourceDocument's CorrectionEvidenceLinks into the .R struct
func (os SourceDocumentSlice) LoadCorrectionEvidenceLinks(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	correctionEvidenceLinks, err := os.CorrectionEvidenceLinks(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.CorrectionEvidenceLinks = nil
		o.R.Loaded.CorrectionEvidenceLinks = true
	}
	for _, o := range os {
		if o == nil {
			continue
		}

		for _, rel := range correctionEvidenceLinks {

			if !(o.HouseholdID == rel.HouseholdID) {
				continue
			}

			if !(o.ID == rel.SourceDocumentID) {
				continue
			}

			rel.R.SourceDocument = o
			rel.R.Loaded.SourceDocument = true

			o.R.CorrectionEvidenceLinks = append(o.R.CorrectionEvidenceLinks, rel)
		}
	}

	return nil
}

