// LoadCreatedByMember loads the sourceDocument's CreatedByMember into the .R struct
func (os SourceDocumentSlice) LoadCreatedByMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	members, err := os.CreatedByMember(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.CreatedByMember = nil
		o.R.Loaded.CreatedByMember = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	sourceDocumentByKey := make(map[uuid.UUID][]*SourceDocument, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		sourceDocumentByKey[o.CreatedBy] = append(sourceDocumentByKey[o.CreatedBy], o)
	}

	for _, rel := range members {

		owners, ok := sourceDocumentByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.CreatedByMember != nil {
				continue
			}

			rel.R.CreatedBySourceDocuments = append(rel.R.CreatedBySourceDocuments, o)

			o.R.CreatedByMember = rel

		}
	}

	return nil
}

