// sourceDocumentC is where relationship counts are stored.
type sourceDocumentC struct {
	CorrectionEvidenceLinks *int64
	DocumentConfirmations   *int64
	EvidenceLinks           *int64
	ExtractionJobs          *int64
	AttachmentsAsChild      *int64
	AttachmentsAsParent     *int64
	SourceObservations      *int64
}

// PreloadCount sets a count in the C struct by name
func (o *SourceDocument) PreloadCount(name string, count int64) error {
	if o == nil {
		return nil
	}

	switch name {
	case "CorrectionEvidenceLinks":
		o.C.CorrectionEvidenceLinks = &count
	case "DocumentConfirmations":
		o.C.DocumentConfirmations = &count
	case "EvidenceLinks":
		o.C.EvidenceLinks = &count
	case "ExtractionJobs":
		o.C.ExtractionJobs = &count
	case "AttachmentsAsChild":
		o.C.AttachmentsAsChild = &count
	case "AttachmentsAsParent":
		o.C.AttachmentsAsParent = &count
	case "SourceObservations":
		o.C.SourceObservations = &count
	}
	return nil
}

